slides=[]
def para(text,cls=''):return f'<p class="{cls}">{text}</p>'
def two(a,b,cls=''):return f'<div class="two {cls}"><div>{a}</div><div>{b}</div></div>'
def table(head,rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{v}</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td data-label="{h(str(head[i]))}">{v}</td>' for i,v in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
def rows(items):return '<div class="rows">'+''.join(f'<div class="row"><strong>{a}</strong><p>{b}</p></div>' for a,b in items)+'</div>'
def code(t):return '<pre><code>'+h(t)+'</code></pre>'
def flow(items):return '<div class="flow">'+'<span class="connector">›</span>'.join(f'<div class="step"><span class="number">{i+1:02}</span><strong>{a}</strong><p>{b}</p></div>' for i,(a,b) in enumerate(items))+'</div>'
def big(value,label,detail=''):return f'<div class="metric-box"><p>{label}</p><div class="big">{value}</div><p class="label">{detail}</p></div>'
def image(name,caption,external=False):
 raw=(P/'assets'/name).read_bytes()
 return f'<figure class="{"external" if external else ""}"><img src="data:image/png;base64,{base64.b64encode(raw).decode()}" alt="{h(caption)}"><figcaption>{caption}</figcaption></figure>'
def add(title,sub,body,message,talk,question,answer,*,chapter='1 실험의 질문',source=None,kind='editorial',dark=False,point=None,caution=None):
 slides.append(dict(title=title,sub=sub,body=body,chapter=chapter,source=source,kind=kind,dark=dark,
                    message=message,talk=talk,question=question,answer=answer,
                    point=point or message,caution=caution or '수업의 합성 사례와 실제 사용자 실험의 결과를 구분합니다.'))
def diagram(nodes,edges,caption,walk=False):
 # Coordinates are authored for each diagram; paths avoid box interiors.
 mid='arrow-'+str(len(slides)+1)
 svg=f'<svg class="architecture" role="img" aria-label="{h(caption)}" viewBox="0 0 1220 390"><defs><marker id="{mid}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z"/></marker></defs>'
 for i,j,label in edges:
  x,y,w,t,sub=nodes[i];xx,yy,ww,tt,ss=nodes[j]
  if abs(y-yy)<5: path=f'M{x+w},{y+42} H{xx-10}';lx=(x+w+xx)/2;ly=y+22
  elif xx>=x+w: path=f'M{x+w},{y+42} H{(x+w+xx)/2} V{yy+42} H{xx-10}';lx=(x+w+xx)/2;ly=min(y,yy)+24
  else: path=f'M{x+w/2},{y+84} V{yy-12} H{xx+ww/2} V{yy-10}';lx=x+w/2+18;ly=(y+84+yy)/2
  svg+=f'<path class="edge" d="{path}" marker-end="url(#{mid})"/>'
  if label:svg+=f'<text class="edge-label" x="{lx}" y="{ly}" text-anchor="middle">{h(label)}</text>'
 for i,(x,y,w,t,sub) in enumerate(nodes):
  svg+=f'<g class="node {"focus" if i==1 else ""}"><rect x="{x}" y="{y}" width="{w}" height="84" rx="2"/><text x="{x+w/2}" y="{y+34}" text-anchor="middle">{h(t)}</text><text class="node-sub" x="{x+w/2}" y="{y+64}" text-anchor="middle">{h(sub)}</text></g>'
 svg+='</svg>'
 fallback='<ol class="architecture-text">'+''.join(f'<li><strong>{h(n[3])}</strong><p>{h(n[4])}</p></li>' for n in nodes)+'</ol>'
 if not walk:return svg+fallback+para(caption,'label')
 steps=[([i],n[3],n[4]) for i,n in enumerate(nodes)]
 return f'<div class="diagram-walk" data-walk="{h(json.dumps(steps,ensure_ascii=False))}">'+svg+fallback+f'<p class="label">{caption}</p><div class="walk-controls"><button class="walk-back" disabled>이전 단계</button><button class="walk-next">흐름 보기</button><button class="walk-reset" disabled>전체 보기</button><p class="walk-caption">전체 구조 · 흐름 보기를 눌러 설명 시작</p></div></div>'
def bars(labels,values,max_value,unit='%',caption=''):
 svg='<svg class="chart" role="img" aria-label="'+h(caption)+'" viewBox="0 0 1160 350">'
 for i,(label,value) in enumerate(zip(labels,values)):
  y=40+i*100;w=value/max_value*740
  svg+=f'<text x="10" y="{y+32}">{h(label)}</text><rect x="280" y="{y}" height="48" width="{w}" fill="{("var(--muted)" if i==0 else "var(--blue)")}"/><text x="{296+w}" y="{y+33}">{value:.1f}{unit}</text>'
 svg+='<line class="axis" x1="280" y1="20" x2="280" y2="300"/></svg>'
 return svg+'<div class="chart-values">'+table(['구분','값'],[[l,f'{v:.1f}{unit}']for l,v in zip(labels,values)])+'</div>'+para(caption,'label')

